import {workNotes, workPaths} from './notes-data.js';
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function prose(text){const parts=String(text).split(/(?<=다\.)\s+/);const groups=[];for(let i=0;i<parts.length;i+=2)groups.push(parts.slice(i,i+2).join(' '));return groups.map(s=>'<p>'+esc(s).replace(/\b(?:[A-Z][A-Z0-9_]*-[A-Z0-9_]+|(?:gt|gs|gv|gcl)_[a-z0-9_]+|sy-subrc|sy-tabix|CHECK_CHANGED_DATA|DATA_CHANGED_FINISHED)\b/g,m=>'<code class="inline-code">'+m+'</code>')+'</p>').join('');}
const storageKey='abap-worknotes-v1';
const cleanMemos=d=>Object.fromEntries(Object.entries(d&&typeof d==='object'?d:{}).filter(([id,v])=>workNotes.some(n=>n.id===id)&&v&&typeof v.text==='string'&&v.text.length<=20000&&Number.isFinite(Date.parse(v.updatedAt))));
let saved={bookmarks:[],recent:[],memos:{}};
try { const d=JSON.parse(localStorage.getItem(storageKey)||'{}');saved={bookmarks:Array.isArray(d.bookmarks)?d.bookmarks:[],recent:Array.isArray(d.recent)?d.recent:[],memos:cleanMemos(d.memos)}; } catch {}
let query='',category='전체',tab='all',highlight=esc;
const get=id=>workNotes.find(n=>n.id===id);
const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(saved));return true;}catch{return false;}};
export const exportNotesState=()=>saved;
export function mergeNotesState(d){if(!d||typeof d!=='object')return;saved.bookmarks=[...new Set([...saved.bookmarks,...(Array.isArray(d.bookmarks)?d.bookmarks:[])])].filter(get);const recent=[...saved.recent,...(Array.isArray(d.recent)?d.recent:[])].filter(r=>get(r.id)&&Number.isFinite(Date.parse(r.time)));const unique=new Map();for(const r of recent.sort((a,b)=>new Date(b.time)-new Date(a.time)))if(!unique.has(r.id))unique.set(r.id,r);saved.recent=[...unique.values()].slice(0,12);for(const [id,m] of Object.entries(cleanMemos(d.memos))){const old=saved.memos[id];if(!old||Date.parse(m.updatedAt)>Date.parse(old.updatedAt))saved.memos[id]=m;}save();}
export const searchNotes=value=>{const words=String(value).trim().toLowerCase().split(/\s+/);return workNotes.filter(n=>words.every(w=>[n.title,n.category,n.summary,saved.memos[n.id]?.text||'',...n.tags,...n.sections.map(s=>s.title+' '+s.text+' '+(s.code||'')+' '+JSON.stringify(s.table||''))].join(' ').toLowerCase().includes(w)));};
const memoForm=n=>`<section class="note-memo" id="note-memo"><h2>내 메모</h2><p>이 글에서 배운 점이나 적용할 코드를 적고 ‘메모 저장’을 누르세요.</p><label for="note-memo-text" class="sr-label">${esc(n.title)}에 대한 내 메모</label><textarea id="note-memo-text" maxlength="20000" rows="6" placeholder="예: 저장 버튼에서 check_changed_data를 먼저 호출하기">${esc(saved.memos[n.id]?.text||'')}</textarea><div><button class="button primary" data-note-memo-save>메모 저장</button><button class="button secondary" data-note-memo-copy>메모 복사</button><span id="note-memo-status" role="status">${saved.memos[n.id]?'저장된 메모가 있습니다.':'이 브라우저에 저장 · 작업 백업에 포함'}</span></div></section>`;
const current=()=>get(location.hash.split('/')[1]);
const saveButton=n=>`<button class="button secondary note-save" data-note-save="${n.id}" aria-pressed="${saved.bookmarks.includes(n.id)}">${saved.bookmarks.includes(n.id)?'★ 저장됨':'☆ 글 저장'}</button>`;
const noteCard=n=>`<article class="note-card"><div><span class="tag">${esc(n.category)}</span><button class="note-bookmark" data-note-save="${n.id}" aria-label="${esc(n.title)} ${saved.bookmarks.includes(n.id)?'저장 해제':'글 저장'}" aria-pressed="${saved.bookmarks.includes(n.id)}">${saved.bookmarks.includes(n.id)?'★':'☆'}</button></div><h3><button data-note-open="${n.id}">${esc(n.title)}</button></h3><p>${esc(n.summary)}</p><div class="note-keywords">${n.tags.slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</div><button class="note-read" data-note-open="${n.id}">흐름과 예제 보기 →</button></article>`;
export function homeWorkPanel(){const recent=saved.recent.slice(0,3).map(r=>get(r.id)).filter(Boolean);return `<section class="work-home"><div class="section-bar"><h2>지금 어떤 작업 중인가요?</h2><button class="text-link" data-nav="notes">실무 노트 ${workNotes.length}개 보기 →</button></div><div class="work-shortcuts">${workPaths.map((p,i)=>`<button data-note-open="${p.ids[0]}"><span>0${i+1}</span><strong>${esc(p.title)}</strong><small>${esc(p.description)}</small></button>`).join('')}</div>${recent.length?`<div class="home-recent"><span>최근 본 글</span>${recent.map(n=>`<button data-note-open="${n.id}">${esc(n.title)} ↗</button>`).join('')}</div>`:''}</section>`;}
function article(n){
 saved.recent=[{id:n.id,time:new Date().toISOString()},...saved.recent.filter(r=>r.id!==n.id)].slice(0,12);save();
 const section=(s,i)=>`<section class="note-section" id="note-section-${i}"><h2><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</h2><div class="note-prose">${prose(s.text)}</div>${s.table?`<div class="note-table-scroll" tabindex="0" aria-label="${esc(s.title)} 표"><table><thead><tr>${s.table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${s.table.rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${s.code?`<div class="note-code"><header><span>ABAP · 적용 예제</span><button data-note-copy-code="${i}">코드 복사</button></header><div class="note-code-where">붙일 위치 · ${esc(s.where)}</div><pre class="code-view" tabindex="0" aria-label="${esc(s.title)}"><code>${highlight(s.code)}</code></pre></div>`:''}</section>`;
 const related=workNotes.filter(x=>x.id!==n.id&&x.category===n.category).slice(0,3);
 return `<div class="note-topline"><button class="text-link" data-note-back>← 실무 노트 목록</button><span>${esc(n.category)} / ${n.sections.length}개 구간</span></div><header class="note-heading"><div class="eyebrow">FLOW FIRST, THEN CODE</div><h1>${esc(n.title)}</h1><p>${esc(n.summary)}</p><div class="note-actions">${saveButton(n)}<button class="button secondary" data-note-copy>글 전체 복사</button><button class="button ghost" data-note-memo-jump>내 메모 ↓</button><button class="button ghost" data-note-permalink>링크 복사</button></div></header><div class="note-layout"><nav class="note-toc" aria-label="본문 목차"><strong>이 글에서 찾기</strong>${n.sections.map((s,i)=>`<button data-note-section="${i}">${String(i+1).padStart(2,'0')} ${esc(s.title)}</button>`).join('')}<span>코드가 길면 ‘크게 보기’<br>읽기 설정에서 줄바꿈 조절</span></nav><article class="note-article">${n.sections.map(section).join('')}${memoForm(n)}<aside class="note-scope">설명·예제는 학습용입니다. 실제 화면·DDIC·업무 설정에 맞춰 적용하고 SAP에서 구문 검사와 테스트를 진행하세요.</aside><section class="note-related"><h2>이어서 보면 좋은 글</h2>${related.map(x=>`<button data-note-open="${x.id}">${esc(x.title)} →</button>`).join('')}<div class="note-sources"><strong>참고 자료</strong>${n.links.map(l=>`<a href="${esc(l.url)}" ${l.url.startsWith('#')?'':'target="_blank" rel="noopener noreferrer"'}>${esc(l.name)} ↗</a>`).join('')}</div></section></article></div>`;
}
export function notesPage(){const n=current();if(n)return article(n);return `<div class="page-heading"><div><div class="eyebrow">FROM QUESTIONS TO WORKING KNOWLEDGE</div><h1>흐름부터 이해하는 실무 노트</h1><p>전표·화면·업로드·오류 해결. 어디에 붙이고, 왜 이 순서로 처리하는지부터 확인하세요.</p></div><span class="syntax-total">${workNotes.length}개 노트 · 단계별 설명</span></div><div class="note-paths">${workPaths.map((p,i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${esc(p.title)}</summary><p>${esc(p.description)}</p><ol>${p.ids.map(id=>`<li><button data-note-open="${id}">${esc(get(id).title)}</button></li>`).join('')}</ol></details>`).join('')}</div><div class="notes-toolbar"><label>노트 검색<input type="search" id="notes-search" value="${esc(query)}" placeholder="예: 전표키, 마지막 수정값, 타입 오류, 임시저장"></label><label>분야<select id="notes-category">${['전체',...new Set(workNotes.map(n=>n.category))].map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div class="note-tabs" role="group" aria-label="볼 노트 선택">${[['all','전체 노트'],['saved','저장한 글'],['recent','최근 본 글'],['memo','메모한 글']].map(([id,label])=>`<button data-note-tab="${id}" aria-pressed="${tab===id}">${label}${id==='saved'?` <span>${saved.bookmarks.length}</span>`:''}</button>`).join('')}<span id="notes-result-count" role="status"></span></div><div id="notes-results"></div><p class="notes-local-note">글 저장과 최근 기록은 이 브라우저에 보관됩니다. 다른 기기로 옮길 때는 ‘내 코드 스타일’의 작업 백업을 이용하세요.</p>`;}
export function renderNotes(){const result=document.querySelector('#notes-results');if(!result)return;let items=searchNotes(query).filter(n=>category==='전체'||n.category===category);if(tab==='saved')items=items.filter(n=>saved.bookmarks.includes(n.id));if(tab==='memo')items=items.filter(n=>!!saved.memos[n.id]?.text.trim());if(tab==='recent')items=saved.recent.map(r=>items.find(n=>n.id===r.id)).filter(Boolean);document.querySelector('#notes-result-count').textContent=`${items.length}개`;const count=document.querySelector('[data-note-tab="saved"] span');if(count)count.textContent=saved.bookmarks.length;document.querySelectorAll('[data-note-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.noteTab===tab)));result.innerHTML=items.length?`<div class="notes-grid">${items.map(noteCard).join('')}</div>`:`<div class="notes-empty"><h2>${tab==='saved'?'저장한 글이 아직 없어요.':tab==='recent'?'아직 읽은 글이 없어요.':tab==='memo'?'아직 메모한 글이 없어요.':'맞는 글을 찾지 못했어요.'}</h2><p>${tab==='saved'?'카드의 ☆ 또는 글 안의 ‘글 저장’을 눌러 모아두세요.':tab==='recent'?'글을 열면 최근 목록에 자동으로 남습니다.':'분야를 전체로 바꾸거나 짧은 키워드로 검색해보세요.'}</p><button class="button secondary" data-note-reset>전체 노트 보기</button></div>`;}
function markdown(n){return `# ${n.title}\n\n${n.summary}\n\n`+n.sections.map(s=>`## ${s.title}\n\n${s.text}\n\n`+(s.table?`| ${s.table.headers.join(' | ')} |\n| ${s.table.headers.map(()=>'---').join(' | ')} |\n${s.table.rows.map(row=>`| ${row.join(' | ')} |`).join('\n')}\n\n`:'')+(s.code?`붙일 위치: ${s.where}\n\n\`\`\`abap\n${s.code}\n\`\`\`\n\n`:'')).join('')+'## 참고 자료\n\n'+n.links.map(l=>`- ${l.name}: ${l.url.startsWith('#')?location.origin+'/'+l.url:l.url}`).join('\n');}
export function bindWorkNotes(deps){highlight=deps.highlight;document.addEventListener('input',e=>{if(e.target.id==='notes-search'){query=e.target.value;renderNotes();}});document.addEventListener('change',e=>{if(e.target.id==='notes-category'){category=e.target.value;renderNotes();}});document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.noteOpen){deps.navigate('notes',b.dataset.noteOpen);return;}if(b.hasAttribute('data-note-back')){deps.navigate('notes');return;}if(b.dataset.noteTab){tab=b.dataset.noteTab;renderNotes();return;}if(b.hasAttribute('data-note-reset')){query='';category='전체';tab='all';deps.navigate('notes');return;}if(b.dataset.noteSave){const id=b.dataset.noteSave;saved.bookmarks=saved.bookmarks.includes(id)?saved.bookmarks.filter(x=>x!==id):[id,...saved.bookmarks];save();document.querySelectorAll(`[data-note-save="${id}"]`).forEach(el=>{const active=saved.bookmarks.includes(id);el.setAttribute('aria-pressed',String(active));el.textContent=el.classList.contains('note-save')?(active?'★ 저장됨':'☆ 글 저장'):(active?'★':'☆');});if(document.querySelector('#notes-results'))renderNotes();deps.toast(saved.bookmarks.includes(id)?'글을 저장했습니다.':'저장한 글에서 해제했습니다.');return;}if(b.dataset.noteSection!==undefined){document.querySelector('#note-section-'+b.dataset.noteSection)?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}const n=current();if(!n)return;if(b.hasAttribute('data-note-memo-jump')){document.querySelector('#note-memo').scrollIntoView({block:'start'});document.querySelector('#note-memo-text').focus();return;}if(b.hasAttribute('data-note-memo-save')){const text=document.querySelector('#note-memo-text').value;const prior=saved.memos[n.id];if(text.trim())saved.memos[n.id]={text,updatedAt:new Date().toISOString()};else delete saved.memos[n.id];const ok=save();if(!ok){if(prior)saved.memos[n.id]=prior;else delete saved.memos[n.id];}document.querySelector('#note-memo-status').textContent=ok?'메모를 저장했습니다.':'저장하지 못했습니다. 공간을 확인하고 내용을 복사해두세요.';deps.toast(ok?'메모를 저장했습니다.':'메모를 저장하지 못했습니다.');return;}if(b.hasAttribute('data-note-memo-copy')){await deps.copy(document.querySelector('#note-memo-text').value,n.title+' · 내 메모');return;}if(b.dataset.noteCopyCode!==undefined)await deps.copy(n.sections[Number(b.dataset.noteCopyCode)].code,n.title+' · 코드');if(b.hasAttribute('data-note-copy'))await deps.copy(markdown(n),n.title+' · 실무 노트');if(b.hasAttribute('data-note-permalink'))await deps.copy(location.origin+'/#notes/'+n.id,n.title+' · 링크');});}
